@code {
    [Parameter]
    public string SortBy { get; set; } = "price_asc";

    [Parameter]
    public int FirstItem { get; set; }

    [Parameter]
    public int LastItem { get; set; }

    [Parameter]
    public int TotalCount { get; set; }

    [Parameter]
